ServerEvents.highPriorityData(function (event) {
  let n = 0;
  CAFE_MENU.forEach(function (row) {
    let id = row[0];
    let base = row[1];
    let json = Object.assign({}, row[2]);
    json.price = Math.max(1, Math.round(base * CAFE_MULTIPLIER));
    try {
      event.addJson(id, json);
      n++;
    } catch (e) {
      console.warn("[하이의 놀이터] 카페 메뉴 덮어쓰기 실패 (" + id + "): " + e);
    }
  });
  console.info(
    "[하이의 놀이터] 카페 메뉴 가격 " + n + "종 적용 (팩 기본가 x " + CAFE_MULTIPLIER + ")"
  );
});
